def balanced(s):
    """Return True if all brackets in s are balanced, ignoring quoted strings."""
    stack = []
    in_string = False
    matching = {')': '(', ']': '[', '}': '{'}
    i = 0

    while i < len(s):
        char = s[i]

        if in_string:
            if char == '\\':
                i += 2
                continue
            if char == '"':
                in_string = False
            i += 1
            continue

        if char == '"':
            in_string = True
        elif char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack.pop() != matching[char]:
                return False

        i += 1

    return not in_string and not stack
